function validate([expression]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 100000) return 'expression needs 1 to 100000 characters.';
  if (/[^01&|()]/.test(expression)) return 'expression may only use 0, 1, &, | and parentheses.';
  let depth = 0;
  let wantTerm = true;
  for (const ch of expression) {
    if (wantTerm) {
      if (ch === '(') depth++;
      else if (ch === '0' || ch === '1') wantTerm = false;
      else if (ch === ')') return 'Parentheses may not be empty, and an operator needs a value after it.';
      else return 'Each operator needs a value on both sides.';
    } else if (ch === '&' || ch === '|') wantTerm = true;
    else if (ch === ')') {
      if (depth === 0) return 'Parentheses must be matched.';
      depth--;
    } else return 'A value must be followed by an operator or a closing parenthesis.';
  }
  if (wantTerm) return 'expression cannot end with an operator or an open parenthesis.';
  if (depth !== 0) return 'Parentheses must be matched.';
  return null;
}

