function minOperationsToFlip(expression) {
  const stack = [];

  for (const ch of expression) {
    if (ch === '(' || ch === '&' || ch === '|') {
      stack.push(ch);
      continue;
    }
    let value;
    let cost;
    if (ch === ')') {
      [value, cost] = stack.pop();
      stack.pop();
    } else {
      value = Number(ch);
      cost = 1;
    }
    const top = stack[stack.length - 1];
    if (top === '&' || top === '|') {
      const operator = stack.pop();
      const [leftValue, leftCost] = stack.pop();
      if (leftValue !== value) {
        cost = 1;
      } else if ((operator === '&' && value === 1) || (operator === '|' && value === 0)) {
        cost = Math.min(leftCost, cost);
      } else {
        cost = Math.min(leftCost, cost) + 1;
      }
      value = operator === '&' ? leftValue & value : leftValue | value;
    }
    stack.push([value, cost]);
  }
  return stack[0][1];
}

