function minOperationsToFlip(expression) {
  // Evaluate a formula without parentheses from left to right.
  const flat = (text) => {
    let value = Number(text[0]);
    for (let i = 1; i < text.length; i += 2) value = text[i] === '&' ? value & Number(text[i + 1]) : value | Number(text[i + 1]);
    return String(value);
  };
  // Collapse innermost parentheses until none are left.
  const evaluate = (text) => {
    while (text.includes('(')) text = text.replace(/\(([01&|]*)\)/g, (_, inside) => flat(inside));
    return flat(text);
  };
  const flip = { '0': '1', '1': '0', '&': '|', '|': '&' };
  const chars = expression.split('');
  const spots = [];
  for (let i = 0; i < chars.length; i++) if (chars[i] in flip) spots.push(i);
  const original = evaluate(expression);
  // Try every set of exactly `left` more changes among spots[start..].
  const search = (start, left) => {
    if (left === 0) return evaluate(chars.join('')) !== original;
    for (let j = start; j < spots.length; j++) {
      const i = spots[j];
      chars[i] = flip[chars[i]];
      const found = search(j + 1, left - 1);
      chars[i] = flip[chars[i]];
      if (found) return true;
    }
    return false;
  };
  // Changing every character gives the complement (De Morgan), so some size always works.
  for (let size = 1; ; size++) if (search(0, size)) return size;
}

