function generate(rand, size) {
  const large = size === 'large';
  if (large && rand() < 0.4) {
    // A balanced tree of one operator over mostly equal digits makes the flip cost grow with its height.
    const operator = rand() < 0.5 ? '&' : '|';
    const usual = operator === '&' ? '0' : '1';
    const tree = (height) => height === 0 ? (rand() < 0.97 ? usual : String(1 - Number(usual))) : '(' + tree(height - 1) + operator + tree(height - 1) + ')';
    return [tree(10 + Math.floor(rand() * 2))];
  }
  for (;;) {
    // Grammar: formula = term (op term)*, term = digit | ( formula ).
    let budget = large ? 2000 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 6);
    const maxDepth = large ? 25 : 3;
    const openChance = large ? 0.25 : 0.35;
    const term = (depth) => {
      if (depth < maxDepth && rand() < openChance) return '(' + formula(depth + 1) + ')';
      budget -= 1;
      return rand() < 0.5 ? '0' : '1';
    };
    const formula = (depth) => {
      let text = term(depth);
      const more = large && depth === 0 ? 1 : 0.55;
      while (budget > 0 && rand() < more) text += (rand() < 0.5 ? '&' : '|') + term(depth);
      return text;
    };
    const expression = formula(0);
    if (expression.length <= 10000) return [expression];
  }
}
